#include "shadow_lifetime.h"
#include <cstdio>

using namespace l4d2_shadow;
#define REQUIRE(condition) do { if (!(condition)) { std::fprintf(stderr, "FAIL line %d: %s\n", __LINE__, #condition); return 1; } } while (false)

Record makeRecord(uint64_t id) {
  Record r;
  r.meta.resourceId = id;
  r.meta.type = Type::Texture2DLevel;
  r.meta.mip = 0;
  r.meta.pool = 0;
  r.meta.usage = kDynamic;
  return r;
}

int main() {
  auto meta = makeRecord(1).meta;
  REQUIRE(oldContentsUnnecessary(meta, kDiscard, true));
  REQUIRE(!oldContentsUnnecessary(meta, 0, true));
  REQUIRE(!oldContentsUnnecessary(meta, kNoOverwrite, true));
  REQUIRE(!oldContentsUnnecessary(meta, kDiscard | kReadonly, true));
  REQUIRE(!oldContentsUnnecessary(meta, kDiscard | kNoOverwrite, true));
  REQUIRE(!oldContentsUnnecessary(meta, kDiscard | 1, true));
  REQUIRE(!oldContentsUnnecessary(meta, kDiscard, false));
  meta.mip = 1; REQUIRE(!oldContentsUnnecessary(meta, kDiscard, true));
  meta.mip = 0; meta.pool = 1; REQUIRE(!oldContentsUnnecessary(meta, kDiscard, true));
  meta.pool = 0; meta.usage = 0; REQUIRE(!oldContentsUnnecessary(meta, kDiscard, true));
  meta.usage = kDynamic; meta.type = Type::CubeFaceLevel;
  REQUIRE(!oldContentsUnnecessary(meta, kDiscard, true));

  Engine engine;
  Record initial = makeRecord(1), preserve = makeRecord(2), discard = makeRecord(3), read = makeRecord(4);
  engine.create(initial, 10 * kMiB, 100);
  engine.lock(initial, 110, 0, true);
  engine.unlock(initial, 120, 0);
  engine.destroy(initial, 1000);
  REQUIRE(engine.destroyed.initialOnly.bytes == 10 * kMiB);
  engine.create(preserve, 20 * kMiB, 1100);
  engine.lock(preserve, 1110, 0, true); engine.unlock(preserve, 1120, 0);
  engine.lock(preserve, 2110, 0, true); engine.unlock(preserve, 2120, 0);
  REQUIRE(preserve.secondDelayValid && preserve.secondLockDelay == 990);
  REQUIRE(preserve.firstRelockDelay == 990 && preserve.maxLockInterval == 1000);
  REQUIRE(preserve.afterUploadPreserve == 1 && preserve.fullLocks == 2);
  engine.destroy(preserve, 2200);
  engine.create(discard, 30 * kMiB, 2300);
  engine.lock(discard, 2310, 0, true); engine.unlock(discard, 2320, 0);
  engine.lock(discard, 12320, kDiscard, true); engine.unlock(discard, 12321, kDiscard);
  engine.destroy(discard, 12400);
  engine.create(read, 40 * kMiB, 13000);
  engine.lock(read, 13001, 0, true); engine.unlock(read, 13002, 0);
  engine.lock(read, 73003, kReadonly, false); engine.unlock(read, 73004, kReadonly);
  engine.destroy(read, 74000);
  REQUIRE(engine.destroyed.all.bytes == 100 * kMiB && engine.destroyed.all.resources == 4);
  REQUIRE(engine.destroyed.discardOnly.bytes == 30 * kMiB);
  REQUIRE(engine.destroyed.potentiallyRequired.bytes == 60 * kMiB);
  REQUIRE(engine.destroyed.readonly.bytes == 40 * kMiB);
  REQUIRE(engine.destroyed.nonpersistent.bytes == 40 * kMiB);
  REQUIRE(engine.destroyed.persistent.bytes == 60 * kMiB);
  REQUIRE(engine.destroyed.delays[0].bytes == 20 * kMiB);
  REQUIRE(engine.destroyed.delays[2].bytes == 30 * kMiB);
  REQUIRE(engine.destroyed.delays[3].bytes == 40 * kMiB);
  REQUIRE(!engine.aliveBytes && !engine.aliveResources && !engine.head);

  // Nested initial locks form one completed upload, regardless of unlock order.
  Record nested = makeRecord(5);
  engine.create(nested, kMiB, 75000);
  engine.lock(nested, 75001, 0, true); engine.lock(nested, 75002, 0, false);
  engine.unlock(nested, 75003, 0);
  REQUIRE(!nested.hasUpload && nested.activeLocks == 1);
  engine.lock(nested, 75004, 0, false);
  REQUIRE(nested.relockedAfterUnlock && !nested.secondDelayValid && !nested.afterUploadLocks);
  engine.unlock(nested, 75005, 0); engine.unlock(nested, 75006, 0);
  REQUIRE(nested.hasUpload && nested.firstUpload == 75006 && !nested.activeLocks);
  const auto unlocked = nested.unlocks;
  engine.unlock(nested, 75007, 0); REQUIRE(nested.unlocks == unlocked);
  engine.destroy(nested, 75008);

  // Realistic byte-weighted LRU sequence: A, B, A at 256 MiB versus 512 MiB.
  Engine cache;
  Record a = makeRecord(10), b = makeRecord(11);
  cache.create(a, 200 * kMiB, 10); cache.create(b, 200 * kMiB, 20);
  cache.lock(a, 30, 0, true); cache.unlock(a, 31, 0);
  cache.lock(b, 40, 0, true); cache.unlock(b, 41, 0);
  cache.lock(a, 50, 0, true); cache.unlock(a, 51, 0);
  REQUIRE(cache.simulations[0].hits == 0 && cache.simulations[0].misses == 3);
  REQUIRE(cache.simulations[1].hits == 1 && cache.simulations[1].misses == 2);
  REQUIRE(cache.simulations[0].preserveMissBytes == 600 * kMiB);
  REQUIRE(cache.simulations[0].coldMissBytes == 400 * kMiB);
  REQUIRE(cache.simulations[0].postUploadPreserveMissBytes == 200 * kMiB);
  REQUIRE(cache.simulations[1].hitBytes == 200 * kMiB);
  cache.lock(b, 60, kDiscard, true); cache.unlock(b, 61, kDiscard);
  REQUIRE(cache.simulations[0].discardMisses == 1);
  REQUIRE(cache.simulations[0].postUploadDiscardMissBytes == 200 * kMiB);
  cache.destroy(a, 70); cache.destroy(b, 71);
  for (const auto& sim : cache.simulations) { REQUIRE(!sim.head && !sim.tail && !sim.residentBytes); }

  // Locked shadows cannot be simulated victims, even above the budget.
  Record pinned = makeRecord(12), other = makeRecord(13);
  cache.create(pinned, 300 * kMiB, 100); cache.create(other, 200 * kMiB, 101);
  cache.lock(pinned, 102, 0, true); cache.lock(pinned, 103, 0, true);
  cache.lock(other, 104, 0, true); cache.unlock(other, 105, 0);
  REQUIRE(pinned.sim[0].resident && !other.sim[0].resident);
  cache.unlock(pinned, 106, 0); REQUIRE(pinned.sim[0].resident);
  cache.unlock(pinned, 107, 0); REQUIRE(!pinned.sim[0].resident);
  cache.destroy(pinned, 108); cache.destroy(other, 109);

  // Burst window spans wall-clock second boundaries and expires at 1000 ms.
  Engine burst;
  Record x = makeRecord(20), y = makeRecord(21), z = makeRecord(22);
  REQUIRE(!burst.create(x, 60 * kMiB, 999));
  REQUIRE(burst.create(y, 40 * kMiB, 1001));
  REQUIRE(burst.windowBytes == 100 * kMiB && burst.windowCount == 2);
  REQUIRE(!burst.create(z, kMiB, 1999));
  REQUIRE(burst.windowBytes == 41 * kMiB && burst.windowCount == 2);
  burst.destroy(x, 2000); burst.destroy(y, 2001); burst.destroy(z, 2002);
  Record failedMap = makeRecord(23);
  const auto incompleteBefore = burst.destroyed.incomplete.bytes;
  burst.create(failedMap, 2 * kMiB, 3000);
  burst.destroy(failedMap, 3001);
  REQUIRE(burst.destroyed.incomplete.bytes - incompleteBefore == 2 * kMiB);
  for (unsigned i = 0; i < 128; ++i) {
    Record reused = makeRecord(100 + i);
    burst.create(reused, kMiB, 4000 + i*2);
    burst.lock(reused, 4000+i*2, 0, true); burst.unlock(reused, 4001+i*2, 0);
    burst.destroy(reused, 4001+i*2);
  }
  REQUIRE(!burst.aliveBytes && !burst.head);
  Record frequent = makeRecord(500);
  const auto frequentBefore = burst.destroyed.frequent.bytes;
  burst.create(frequent, 7 * kMiB, 8000);
  for (unsigned i = 0; i < 8; ++i) {
    burst.lock(frequent, 8001 + 1000*i, 0, false);
    burst.unlock(frequent, 8002 + 1000*i, 0);
  }
  REQUIRE(frequent.partialLocks == 8 && frequent.afterUploadLocks == 7 && frequent.afterUploadPreserve == 7);
  burst.destroy(frequent, 16000);
  REQUIRE(burst.destroyed.frequent.bytes - frequentBefore == 7 * kMiB);
  std::puts("PASS: conservative DISCARD, byte-weighted categories, nested uploads, intervals, simulated LRU and rolling bursts");
  return 0;
}
